#!/usr/bin/env python3
"""Bundle verified Leaflet locally so existing signed receivers need no new URLs."""
import argparse,base64,hashlib,json,re
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]


def bundle():
    vendor=ROOT/'home_assistant/vendor/leaflet'
    metadata=json.loads((vendor/'package-integrity.json').read_text())
    for name,digest in metadata['files'].items():
        if hashlib.sha256((vendor/name).read_bytes()).hexdigest()!=digest:raise ValueError('Leaflet vendor checksum mismatch: '+name)
    images={name:'data:image/png;base64,'+base64.b64encode((vendor/name).read_bytes()).decode() for name in metadata['files'] if name.endswith('.png')}
    css=(vendor/'leaflet.css').read_text()
    for name,data in images.items():css=css.replace('images/'+name,data)
    js=re.sub(r'//# sourceMappingURL=.*','',(vendor/'leaflet.js').read_text())
    license=(vendor/'LICENSE').read_text()
    prefix='/* Generated by dev/build_drive_console.py. Leaflet 1.9.4, BSD-2-Clause.\n'+license+'\n*/\n'
    prefix+="const LEAFLET_CSS="+json.dumps(css)+";\nconst LEAFLET=typeof document==='undefined'?null:(()=>{const previous=window.L;const module={exports:{}};const exports=module.exports;\n"+js+"\nconst library=module.exports;if(window.L===library)window.L=previous;library.Icon.Default.mergeOptions("+json.dumps({'iconUrl':images['marker-icon.png'],'iconRetinaUrl':images['marker-icon-2x.png'],'shadowUrl':images['marker-shadow.png']})+");return library;})();\n"
    prefix+='const DASHBOARD_CSS='+json.dumps((ROOT/'home_assistant/dashboard_theme.css').read_text())+';\n'
    return prefix+(ROOT/'home_assistant/ui_runtime.js').read_text()+'\n'+(ROOT/'home_assistant/drive_console.source.js').read_text()+'\n'+(ROOT/'home_assistant/map_layers.js').read_text()+'\n'+(ROOT/'home_assistant/service_cards.js').read_text()


def main():
    parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('--check',action='store_true');args=parser.parse_args()
    path=ROOT/'home_assistant/drive_console.js';expected=bundle()
    if args.check:
        if path.read_text()!=expected:raise SystemExit('Drive Console bundle is stale; run python3 dev/build_drive_console.py')
        print('Drive Console bundle and verified Leaflet assets match')
    else:path.write_text(expected)

if __name__=='__main__':main()
